using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.InputSystem;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class OnLookRecover {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/Diagnostics/OnLook_20261109/"));
 static string Flags()=>typeof(InputDevice).GetField("m_DeviceFlags",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(Mouse.current).ToString();
 public static object Run(){var mouse=Mouse.current;if(mouse==null)throw new Exception("No mouse");var prior=new{mouse.enabled,flags=Flags()};InputSystem.EnableDevice(mouse);var s=SceneManager.GetActiveScene();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).Where(c=>c).ToArray();var references=all.Where(c=>c.GetType().Name=="PlayerLook"||c.GetType().Name=="CinemachineVirtualCamera").Select(c=>new{type=c.GetType().Name,c.enabled,refs=c.GetType().GetFields(BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Where(f=>typeof(UnityEngine.Object).IsAssignableFrom(f.FieldType)).Select(f=>{var o=f.GetValue(c)as UnityEngine.Object;return new{name=f.Name,valid=o!=null,value=o?o.name:null};}).ToArray()}).ToArray();var result=new{prior,after=new{mouse.enabled,flags=Flags()},scene=s.path,s.isDirty,references};File.WriteAllText(H+"recovery.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
